import Navbar from "../components/Navbar";
import Hero from "../components/Hero";
import Problems from "../components/Problems";
import Solutions from "../components/Solutions";
import Footer from "../components/Footer";

function Home() {
  return (
    <>
      <Navbar />
      <Hero />
      <Problems />
      <Solutions />
      <Footer />
    </>
  );
}

export default Home;
